  brush.beginShape();
  brush.vertex(0, 200);
  brush.vertex(200, 100);
  brush.vertex(400, 200);
  brush.vertex(200, 300);
  brush.endShape(true);

  // Clouds
  brush.fill("#e0f2f5", 40);
  brush.fillBleed(0.8);
  brush.beginShape();
  brush.vertex(0, 250);
  brush.vertex(200, 150);
  brush.vertex(400, 250);
  brush.vertex(200, 350);
  brush.endShape(true);

  // Horizon
  brush.fill("#e08a72", 80);
  brush.fillBleed(0.4);
